func (s *Server) getAuthoringSchema(w http.ResponseWriter, r *http.Request) {
	kind := r.PathValue("kind")
	schema, err := insightsschema.Document(kind)
	if errors.Is(err, insightsschema.ErrUnknownKind) {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "authoring schema is unavailable")
		return
	}
	response := authoringSchemaResponse{
		SchemaVersion: 1, Kind: kind, Schema: schema,
		Examples: authoringSchemaExamples(kind),
		Notes: []string{
			"Examples are illustrative documents, not live telemetry. Replace metrics-provider-id using list_insights_providers and discover metric and label names before querying.",
			"The service additionally validates semantic rules, references, unique identifiers, typed bindings, query literal boundaries and plugin configuration. JSON Schema alone does not express every runtime check.",
			"Examples containing queryRef require their corresponding saved_query example first: service-request-rate or service-records. Widget queryRef is authoritative; unavailable references fail without falling back to the required query field. Rich-chart examples without queryRef use explicit illustrative queries; discover the real provider's metrics, labels or records columns before adapting them.",
			"For built-in time-series charts, options.seriesColors is an ordered array of up to 24 {label,value,color} rules. Match an exact metric label/value to a six-digit hex color; the first matching rule wins, then widget.color and the default palette supply fallbacks. These rules preserve series identity when provider order changes and are used by chart lines, legends, tooltips, and matched prior-period overlays.",
			"Single value options.staleAfterSeconds is optional and accepts an integer from 1 to 2678400. It warns when the primary series' newest valid returned sample is older than that threshold relative to the selected range end. No usable observation or a failed query has unknown freshness. The warning and query_dashboard freshness describe returned samples, not underlying scrape or ingestion health.",
			"Use get_dashboard or get_saved_query before editing. Preserve unchanged fields and supply the exact current ETag when updating.",
			"Records examples require a records-capable provider from list_insights_providers and a dashboard service variable. The SQL example needs a PostgreSQL provider with reader access to your reporting view; replace the illustrative table and columns. Bind SQL values with $1 and an unquoted {{service}} in the JSON parameters array, never inside the SQL body.",
			"PostgreSQL does not automatically filter SQL by the selected dashboard range. To use it, include {\"range\":\"start\"} and/or {\"range\":\"end\"} as values in the SQL envelope's parameters array and reference their positional $n placeholders in the SQL. They bind the requested boundaries as UTC timestamps, not interpolated SQL text. SQL comparison operators determine endpoint inclusivity; a missing referenced boundary or reversed range is an error. The service-history saved-query example shows inclusive boundaries with a service parameter.",
			"record-table config.showRowNumbers is an optional boolean, default false. It numbers loaded rows in their displayed filtered, sorted and paginated order; the numbers are not source-wide ranks.",
			"Built-in records plugins use type=plugin and dataKind=records: record-table config {columns?:string[1..64],pageSize?:5..100,density?:compact|comfortable,showSearch?:boolean,timeSelection?:{start:string,duration:string,durationUnit:milliseconds|seconds|minutes,paddingSeconds?:0..86400},cellStyles?:[{column:string,display:bar|bar-segments|color-text|color-background|sparkline|status-badge,min?:number,max?:number,unit?:string,segments?:4..60}]}; defaults are 20 rows, comfortable density and search shown. Compact rows preserve sorting and selection. Time selection requires a timestamp column and positive duration, and changes only the runtime dashboard range on explicit activation. Up to 16 unique result columns may have cell styles; bar and color styles require numbers, while sparkline requires a string. Bar cells require explicit finite min<max; signed scales anchor at zero, filtering never rescales bars, and out-of-scale values retain their exact reading. Color modes use widget options.thresholds or widget.color; backgrounds choose readable text. Nulls remain unknown. Bar and segmented bar styles require min/max; segmented bars optionally accept 4..60 segments. Unit may be set for numeric and sparkline styles. A sparkline string contains an ordered JSON array of up to 240 objects {timestamp:ISO-8601,value:number|null}; missing values remain gaps, timestamps must be unique and ordered, and its visible value is the latest observation including null. It uses only the returned row, never another query. Other records plugins: record-list {title:string,body?:string,subtitle?:string,url?:string,status?:string}; record-treemap {label:string,value:string,group?:string}; record-matrix {x:string,y:string,value:string,min?:number,max?:number}. Config strings name result columns, not expressions.",
			"record-table additionally supports display=status-badge for a string column with optional mappings:[{value:string,color:#RRGGBB}] (at most 16 unique exact values). Mapped values have a colored dot; unmapped and missing values remain neutral. Status badges cannot use units, numeric scales, segments or barColorMode. For bar and bar-segments, optional barColorMode=gradient|value controls whether the track shows threshold bands or uses the observation's threshold color; the default is gradient. These options are illustrated by the service-capacity widget example.",
			"A record-table sparkline cellStyle may set thresholdColumn to the name of a numeric result column. The row's value selects a widget options.thresholds color for the whole sparkline; it does not color individual historical observations. Missing or non-finite row values and absent thresholds use a neutral color. Omitting thresholdColumn keeps the widget color. The history string itself is unchanged and no additional query runs.",
			"record-treemap config {label:string,value:string,group?:string,colorField?:string,colorMin?:number,colorMax?:number} names returned columns. Positive finite value observations determine tile area; group adds labeled sector or category groups. colorField is an optional numeric column independent of area; set both finite colorMin and colorMax with min<max for a fixed scale, or omit both to use the displayed data range. Missing color observations are shown as unknown, not treated as zero. The market-composition widget example demonstrates grouping and fixed color bounds.",
			"Record charts: records-line and records-bar config {x:string,y:string[],group?:string,rightAxis?:string[],annotations?:[{x:string|number,label:string}]}; y contains 1..8 numeric columns and rightAxis is a subset. Metric plugins include pie {donut?:boolean} and status-history {maxSeries?:1..24,maxPoints?:8..120,labelField?:string,showTimeAxis?:boolean,segmented?:boolean}; labelField selects a series label for each lane, showTimeAxis shows the shared UTC time range and segmented adds fine boundaries to recorded samples. Status-history selectionBindings can update dashboard variables from the activated sample's labels, series name or value; hover and focus do not change filters. Use dataKind=metrics for those.",
			"Monitor status views use type=plugin and dataKind=metrics. status-grid config {maxSeries?:1..2048} shows each returned series' latest recorded sample, including null as unknown; default maximum is 512. uptime-calendar and uptime-timeline config {maxDays?:7..366,maxSeries?:1..24} group recorded samples by UTC day, defaulting to 90 days and 1 or 8 series respectively. Days containing different threshold states or missing observations are mixed; days without finite observations are unknown. They do not calculate uptime percentages or infer continuous availability. For binary up metrics, default thresholds are red below 1 and green from 1; configure options.thresholds for other semantics.",
			"small-multiples uses type=plugin and dataKind=metrics, config {maxSeries?:1..12,columns?:1..6,maxPoints?:8..240}; defaults are 6 series, 3 columns and 120 points. It presents each returned series with a shared time and value domain. Null samples remain gaps, and tooltip selection reports an exact recorded point.",
			"Rich metric plugins use type=plugin and dataKind=metrics. stacked-timeseries config {display?:area|bar,maxSeries?:1..12,maxPoints?:12..240,legendDisplay?:compact|table,legendPosition?:bottom|right}; defaults are area, 8 series, 120 points, compact legend below. Input series must be timestamp-aligned additive observations; positive and negative values stack separately. Missing observations leave gaps rather than inventing a complete total.",
			"directional-traffic config {directionLabel?:string,outboundValue?:string,maxSeries?:1..12,maxPoints?:12..240,legendDisplay?:compact|table,legendPosition?:bottom|right}; defaults are direction, outbound, 8 series, 120 points, compact legend below. Input observations must be nonnegative; series whose direction label equals outboundValue are drawn below zero while inspection retains the original positive value. Other series remain above zero. Label fields use metric label names, not expressions.",
			"Stacked and directional table legends show Current, Mean and Max from all returned valid-timestamp observations before display downsampling. Current is the latest raw observation, including unknown; Mean is the arithmetic mean of finite samples, not a time-weighted average; Max is the maximum finite sample. Statistics never use cumulative stack heights or direction-negated display values. A right legend moves below the plot in widgets narrower than 680px.",
			"A timeseries, stacked-timeseries or directional-traffic widget may use annotationSource {queryRef:{id,bindings?},timestampColumn:string,endColumn?:string,labelColumn:string,severityColumn?:string} to overlay up to 20 recorded events from a records saved query. An optional end column renders a shaded interval; null means a point event. Dashboard variable and constant bindings work as for the main query. Timestamps must be explicit ISO datetimes with timezones or Unix milliseconds. The query is independently collected by query_dashboard as annotationSignalId, with annotationColumns identifying source fields; failures are reported separately without hiding the metric signal. Events overlapping the time window are shown.",
			"distribution-heatmap config {bucketLabel?:string,bucketUnit?:string,densityUnit?:string,group?:{label:string},aggregation?:none|sum,colorScale?:linear|logarithmic,maxBuckets?:1..48,maxColumns?:8..120}; defaults are le, widget unit, observations/s, no group filter, none, linear color, 24 buckets and 60 columns. Logarithmic color spreads positive densities between the smallest and largest values in shown buckets before time sampling, keeping zero separate; it never changes query values. Input must contain cumulative histogram buckets, including numeric bucket boundaries or +Inf. Use query-side rates when densityUnit is per second; this chart only differences adjacent buckets. Multiple histogram groups require exact group labels or explicit sum, and summed groups must have identical boundaries. Group accepts at most 8 exact label matches. Non-monotonic/negative or missing bucket observations remain unknown.",
			"threshold-gauge config {label?:string,display?:linear|segmented|radial,orientation?:horizontal|vertical,segments?:8..60,showThresholds?:boolean,seriesMode?:first|all,columns?:1..12,maxSeries?:1..12,showStatus?:boolean}; defaults are linear, horizontal, 24 segments, threshold labels shown, first series and at most 6 gauges. showStatus defaults to false and, for a horizontal linear or segmented all-series bank, adds the matching threshold label and color beside each reading; a missing observation is Unknown and an unlabeled threshold is Observed. It does not apply to radial, vertical, or single-series gauges. Horizontal bars align label, track and value; vertical bars fill bottom-up. Orientation does not alter radial arcs. All-series banks default to 3 columns for radial, 4 for vertical bars and 1 for horizontal rows; narrow panels wrap. Segmented tracks use a continuous threshold scale when four-pixel cells cannot fit. Use widget options.min/max for the scale, options.thresholds for colored limits, options.decimals for display precision and options.showLegend for shared bank bounds/threshold labels. Each gauge uses its own latest observation, including unknown; hidden series are disclosed. Full labels and exact observations remain accessible when compact labels are ellipsized.",
			"connection-map uses dataKind=records with config {latitude?:string,longitude?:string,label?:string,value?:string,status?:string,showLocations?:boolean,maxPoints?:1..500}; coordinate/label defaults are latitude, longitude, label and maxPoints defaults to 120. Latitude and longitude must be numeric degrees within [-90,90] and [-180,180]; optional value must be numeric. Positions come only from returned coordinates, never inferred from IP addresses. Invalid coordinates and omitted rows are disclosed. Set showLocations=false for a map-only view; exact point inspection remains available and geographic proportions are preserved.",
			"geo-heatmap uses dataKind=records with config {mode?:map|grid,latitude?:string,longitude?:string,label?:string,value?:string,aggregation?:count|sum|mean,radius?:8..36,maxRecords?:1..500,gridColumns?:8..48}. Map mode bins the supplied coordinates; grid mode shows one record per hexagon. Sum and mean require a numeric value field and do not invent missing values. Tooltips report recorded observations; empty locations are unobserved. Selection and tooltip bindings can use only labels shared by all records in a bin and its exact aggregate; no timestamp is fabricated. Use options.tooltipView for a configured detail query or saved-query subwidget.",
			"pipeline-topology uses dataKind=records with config {source?:string,target?:string,value?:string,status?:string,maxNodes?:2..64,maxEdges?:1..200}; defaults are source, target, 32 nodes and 80 edges. Source/target fields name stages; optional value must be numeric. Duplicate source/target pairs aggregate finite values only when every contributing row is finite, otherwise the value is unknown. Cycles remain explicit and limits disclose omitted nodes/edges.",
			"incident-calendar uses dataKind=records with config {date?:string,value?:string,label?:string,status?:string,aggregation?:count|sum|max,colorMode?:intensity|thresholds,months?:1..6,endDate?:YYYY-MM-DD}; defaults are date, count, intensity colors and 3 months ending at the latest returned date. Dates use UTC and must be valid calendar dates or ISO timestamps; numeric dates are Unix milliseconds. Sum/max require a numeric value field, while count counts observed rows. In thresholds colorMode, options.thresholds color the aggregated daily value; unmapped values remain neutral. Days without observations stay unknown rather than becoming zero. Explicit endDate controls the visible UTC month window.",
		},
	}
	encoded, err := json.Marshal(response)
	if err != nil || len(encoded) > maxSchemaResponseBytes {
		writeError(w, http.StatusInternalServerError, "authoring schema exceeds its response limit")
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	if _, err := w.Write(encoded); err != nil {
		return // A disconnected client cannot receive a replacement response.
	}
}

func authoringSchemaExamples(kind string) []json.RawMessage {
	examples := []json.RawMessage{authoringSchemaExample(kind)}
	switch kind {
	case "widget":
		return append(examples, json.RawMessage(schemaRecordWidgetExample), json.RawMessage(schemaStackedWidgetExample), json.RawMessage(schemaGaugeBankExample), json.RawMessage(schemaDistributionExample), json.RawMessage(schemaConnectionMapExample), json.RawMessage(schemaStyledTableExample), json.RawMessage(schemaGroupedTreemapExample))
	case "saved_query":
		return append(examples, json.RawMessage(schemaRecordQueryExample), json.RawMessage(schemaRangeRecordQueryExample))
	default:
		return examples
	}
}

func authoringSchemaExample(kind string) json.RawMessage {
	switch kind {
	case "dashboard":
		return json.RawMessage(schemaDashboardExample)
	case "widget":
		return json.RawMessage(schemaWidgetExample)
	default:
		return json.RawMessage(schemaSavedQueryExample)
	}
}
